-- Fresh isolated deployments only. No upgrades of an existing queue are implicit.
CREATE SCHEMA ai_review_v4 AUTHORIZATION __OWNER__;
SET ROLE __OWNER__;
CREATE SEQUENCE ai_review_v4._ddl_epoch;
CREATE TABLE ai_review_v4._meta(singleton boolean PRIMARY KEY CHECK(singleton),owner_oid oid NOT NULL,app_oid oid NOT NULL,tenant text NOT NULL,deployment text NOT NULL,epoch bigint NOT NULL,key_check jsonb NOT NULL);
INSERT INTO ai_review_v4._meta VALUES(true,__OWNER_LITERAL__::regrole::oid,__APP_LITERAL__::regrole::oid,__TENANT__,__DEPLOYMENT__,0,__KEY_CHECK__);
CREATE TABLE ai_review_v4._ctx(pid integer PRIMARY KEY,tx bigint NOT NULL);
CREATE TABLE ai_review_v4.requests(id uuid PRIMARY KEY,header jsonb NOT NULL,header_digest text NOT NULL,request_sealed jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE ai_review_v4.jobs(id uuid PRIMARY KEY REFERENCES ai_review_v4.requests(id),ordinal bigint GENERATED ALWAYS AS IDENTITY UNIQUE,status text NOT NULL CHECK(status IN('READY','RUNNING','RETRY','RESULT_READY')),owner uuid,token uuid,fence bigint NOT NULL DEFAULT 0,lease_until timestamptz,available_at timestamptz NOT NULL DEFAULT clock_timestamp(),dispatches integer NOT NULL DEFAULT 0 CHECK(dispatches>=0),network_failures integer NOT NULL DEFAULT 0 CHECK(network_failures BETWEEN 0 AND 3),last_failure_fence bigint,last_dispatch_fence bigint,outcome_sealed jsonb,outcome_digest text,completed_at timestamptz,error_code text);
CREATE INDEX ai_review_available ON ai_review_v4.jobs(ordinal) WHERE status<>'RESULT_READY';
CREATE FUNCTION ai_review_v4._guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_OP='TRUNCATE' OR TG_TABLE_NAME='_meta' OR NOT EXISTS(SELECT 1 FROM ai_review_v4._ctx WHERE pid=pg_backend_pid() AND tx=txid_current()) OR (TG_TABLE_NAME='requests' AND TG_OP<>'INSERT') OR (TG_TABLE_NAME='jobs' AND TG_OP='DELETE') THEN RAISE EXCEPTION 'AI_REVIEW_DIRECT_WRITE';END IF;
 IF TG_TABLE_NAME='jobs' AND TG_OP='UPDATE' THEN IF OLD.status='RESULT_READY' OR OLD.id<>NEW.id OR OLD.ordinal<>NEW.ordinal OR OLD.dispatches>NEW.dispatches OR OLD.fence>NEW.fence THEN RAISE EXCEPTION 'AI_REVIEW_RESULT_IMMUTABLE';END IF;END IF;
 IF TG_OP='DELETE' THEN RETURN OLD;ELSE RETURN NEW;END IF;
END $$;
DO $$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['_meta','requests','jobs'] LOOP
 EXECUTE format('CREATE TRIGGER ai_review_write_guard BEFORE INSERT OR UPDATE OR DELETE ON ai_review_v4.%I FOR EACH ROW EXECUTE FUNCTION ai_review_v4._guard()',t);
 EXECUTE format('CREATE TRIGGER ai_review_truncate_guard BEFORE TRUNCATE ON ai_review_v4.%I FOR EACH STATEMENT EXECUTE FUNCTION ai_review_v4._guard()',t);
 EXECUTE format('ALTER TABLE ai_review_v4.%I ENABLE ALWAYS TRIGGER ai_review_write_guard',t);EXECUTE format('ALTER TABLE ai_review_v4.%I ENABLE ALWAYS TRIGGER ai_review_truncate_guard',t);
END LOOP;END $$;
CREATE FUNCTION ai_review_v4._assert() RETURNS void LANGUAGE plpgsql AS $$ DECLARE m ai_review_v4._meta;r record;e bigint;BEGIN
 PERFORM pg_advisory_xact_lock_shared(1229213011,4);LOCK TABLE ai_review_v4._meta,ai_review_v4._ctx,ai_review_v4.requests,ai_review_v4.jobs IN ACCESS SHARE MODE;
 SELECT * INTO STRICT m FROM ai_review_v4._meta;
 IF current_user::regrole::oid<>m.owner_oid OR session_user::regrole::oid<>m.app_oid THEN RAISE EXCEPTION 'AI_REVIEW_AUTHORITY';END IF;
 FOR r IN SELECT * FROM pg_roles WHERE oid IN(m.owner_oid,m.app_oid) LOOP IF r.rolsuper OR r.rolcreatedb OR r.rolcreaterole OR r.rolinherit OR r.rolreplication OR r.rolbypassrls OR r.rolcanlogin<>(r.oid<>m.owner_oid) OR EXISTS(SELECT 1 FROM pg_auth_members WHERE member=r.oid OR roleid=r.oid) THEN RAISE EXCEPTION 'AI_REVIEW_AUTHORITY';END IF;END LOOP;
 IF (SELECT count(*) FROM pg_roles WHERE oid IN(m.owner_oid,m.app_oid))<>2 OR (SELECT count(*) FROM pg_trigger WHERE tgrelid IN('ai_review_v4._meta'::regclass,'ai_review_v4.requests'::regclass,'ai_review_v4.jobs'::regclass) AND tgname IN('ai_review_write_guard','ai_review_truncate_guard') AND tgenabled='A')<>6 OR (SELECT count(*) FROM pg_event_trigger WHERE evtname IN('ai_review_ddl_start_v4','ai_review_ddl_end_v4','ai_review_sql_drop_v4') AND evtenabled='A')<>3 THEN RAISE EXCEPTION 'AI_REVIEW_AUTHORITY';END IF;
 SELECT CASE WHEN is_called THEN last_value ELSE 0 END INTO e FROM ai_review_v4._ddl_epoch;IF e<>m.epoch THEN RAISE EXCEPTION 'AI_REVIEW_SCHEMA_EPOCH';END IF;
END $$;
CREATE FUNCTION ai_review_v4.verify_v4() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,ai_review_v4,pg_temp AS $$ DECLARE m ai_review_v4._meta;BEGIN PERFORM ai_review_v4._assert();SELECT * INTO STRICT m FROM ai_review_v4._meta;RETURN jsonb_build_object('deployment',m.deployment,'tenantId',m.tenant,'databaseOid',(SELECT oid::text FROM pg_database WHERE datname=current_database()),'roleOid',session_user::regrole::oid::text,'keyCheck',m.key_check);END $$;
CREATE FUNCTION ai_review_v4._view(wanted uuid) RETURNS jsonb LANGUAGE sql STABLE AS $$ SELECT jsonb_build_object('header',r.header,'requestSealed',r.request_sealed,'headerDigest',r.header_digest,'status',j.status,'owner',j.owner,'token',j.token,'fence',j.fence::text,'leaseUntil',j.lease_until,'dispatches',j.dispatches,'networkFailures',j.network_failures,'outcomeSealed',j.outcome_sealed,'outcomeDigest',j.outcome_digest,'errorCode',j.error_code) FROM ai_review_v4.requests r JOIN ai_review_v4.jobs j USING(id) WHERE r.id=wanted $$;
CREATE FUNCTION ai_review_v4.enqueue_v4(header jsonb,header_digest text,sealed jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,ai_review_v4,pg_temp AS $$ DECLARE m ai_review_v4._meta;wanted_id uuid;prior ai_review_v4.requests;BEGIN
 PERFORM pg_advisory_xact_lock_shared(1229213011,1);PERFORM pg_advisory_xact_lock_shared(1229213011,2);PERFORM ai_review_v4._assert();SELECT * INTO STRICT m FROM ai_review_v4._meta;
 IF header IS NULL OR jsonb_typeof(header)<>'object' OR (SELECT count(*) FROM jsonb_object_keys(header))<>10 OR header->>'format' IS DISTINCT FROM 'IDMS_AI_REVIEW_TRANSPORT_V4_1' OR header->>'deployment' IS DISTINCT FROM m.deployment OR header->>'tenantId' IS DISTINCT FROM m.tenant OR header->>'databaseOid' IS DISTINCT FROM (SELECT oid::text FROM pg_database WHERE datname=current_database()) OR coalesce(header->>'requestId','')!~'^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$' OR coalesce(header->>'objectId','')!~'^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$' OR coalesce(header->>'requestDigest','')!~'^[a-f0-9]{64}$' OR coalesce(header->>'snapshotDigest','')!~'^[a-f0-9]{64}$' OR coalesce(header->>'configDigest','')!~'^[a-f0-9]{64}$' OR coalesce(header->>'batchVersion','')!~'^[1-9][0-9]{0,8}$' OR header_digest IS NULL OR header_digest!~'^[a-f0-9]{64}$' OR sealed IS NULL OR jsonb_typeof(sealed)<>'object' OR octet_length(sealed::text)>70000 THEN RAISE EXCEPTION 'AI_REVIEW_INPUT';END IF;
 wanted_id:=(header->>'requestId')::uuid;PERFORM pg_advisory_xact_lock(hashtextextended('ai-review:'||m.deployment,0));SELECT * INTO prior FROM ai_review_v4.requests r WHERE r.id=wanted_id;
 IF FOUND THEN IF prior.header IS DISTINCT FROM header OR prior.header_digest IS DISTINCT FROM header_digest THEN RAISE EXCEPTION 'AI_REVIEW_REQUEST_CONFLICT';END IF;RETURN ai_review_v4._view(wanted_id);END IF;
 IF (SELECT count(*) FROM ai_review_v4.jobs WHERE status<>'RESULT_READY')>=10000 THEN RAISE EXCEPTION 'AI_REVIEW_BACKPRESSURE';END IF;
 INSERT INTO ai_review_v4._ctx VALUES(pg_backend_pid(),txid_current());INSERT INTO ai_review_v4.requests VALUES(wanted_id,header,header_digest,sealed,clock_timestamp());INSERT INTO ai_review_v4.jobs(id,status) VALUES(wanted_id,'READY');DELETE FROM ai_review_v4._ctx WHERE pid=pg_backend_pid();RETURN ai_review_v4._view(wanted_id);
END $$;
CREATE FUNCTION ai_review_v4.read_v4(wanted uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,ai_review_v4,pg_temp AS $$ BEGIN PERFORM ai_review_v4._assert();RETURN ai_review_v4._view(wanted);END $$;
CREATE FUNCTION ai_review_v4.claim_v4(owner uuid,token uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,ai_review_v4,pg_temp AS $$ DECLARE j ai_review_v4.jobs;BEGIN
 PERFORM ai_review_v4._assert();IF owner IS NULL OR token IS NULL THEN RAISE EXCEPTION 'AI_REVIEW_INPUT';END IF;
 SELECT * INTO j FROM ai_review_v4.jobs q WHERE q.status<>'RESULT_READY' AND q.available_at<=clock_timestamp() AND (q.status<>'RUNNING' OR q.lease_until<=clock_timestamp()) ORDER BY q.ordinal FOR UPDATE SKIP LOCKED LIMIT 1;IF NOT FOUND THEN RETURN NULL;END IF;
 INSERT INTO ai_review_v4._ctx VALUES(pg_backend_pid(),txid_current());UPDATE ai_review_v4.jobs SET status='RUNNING',owner=claim_v4.owner,token=claim_v4.token,fence=fence+1,lease_until=clock_timestamp()+interval '30 seconds',error_code=NULL WHERE id=j.id;DELETE FROM ai_review_v4._ctx WHERE pid=pg_backend_pid();RETURN ai_review_v4._view(j.id);
END $$;
CREATE FUNCTION ai_review_v4._lease(wanted uuid,owner uuid,token uuid,fence bigint) RETURNS ai_review_v4.jobs LANGUAGE plpgsql AS $$ DECLARE j ai_review_v4.jobs;BEGIN SELECT * INTO j FROM ai_review_v4.jobs q WHERE id=wanted FOR UPDATE;IF NOT FOUND OR j.status<>'RUNNING' OR j.owner IS DISTINCT FROM owner OR j.token IS DISTINCT FROM token OR j.fence IS DISTINCT FROM fence OR j.lease_until<=clock_timestamp() THEN RAISE EXCEPTION 'AI_REVIEW_LEASE_LOST';END IF;RETURN j;END $$;
CREATE FUNCTION ai_review_v4.renew_v4(wanted uuid,owner uuid,token uuid,fence bigint) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,ai_review_v4,pg_temp AS $$ BEGIN PERFORM ai_review_v4._assert();PERFORM ai_review_v4._lease(wanted,owner,token,fence);INSERT INTO ai_review_v4._ctx VALUES(pg_backend_pid(),txid_current());UPDATE ai_review_v4.jobs SET lease_until=clock_timestamp()+interval '30 seconds' WHERE id=wanted;DELETE FROM ai_review_v4._ctx WHERE pid=pg_backend_pid();RETURN true;END $$;
CREATE FUNCTION ai_review_v4.dispatch_v4(wanted uuid,owner uuid,token uuid,fence bigint) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,ai_review_v4,pg_temp AS $$ DECLARE j ai_review_v4.jobs;BEGIN
 PERFORM ai_review_v4._assert();j:=ai_review_v4._lease(wanted,owner,token,fence);IF j.last_dispatch_fence=fence THEN RETURN j.dispatches;END IF;IF j.network_failures>=3 THEN RAISE EXCEPTION 'AI_REVIEW_NETWORK_LIMIT';END IF;
 INSERT INTO ai_review_v4._ctx VALUES(pg_backend_pid(),txid_current());UPDATE ai_review_v4.jobs SET dispatches=dispatches+1,last_dispatch_fence=dispatch_v4.fence WHERE id=wanted RETURNING * INTO j;DELETE FROM ai_review_v4._ctx WHERE pid=pg_backend_pid();RETURN j.dispatches;
END $$;
CREATE FUNCTION ai_review_v4.network_failure_v4(wanted uuid,owner uuid,token uuid,fence bigint) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,ai_review_v4,pg_temp AS $$ DECLARE j ai_review_v4.jobs;BEGIN
 PERFORM ai_review_v4._assert();j:=ai_review_v4._lease(wanted,owner,token,fence);IF j.last_dispatch_fence IS DISTINCT FROM fence THEN RAISE EXCEPTION 'AI_REVIEW_NOT_DISPATCHED';END IF;IF j.last_failure_fence=fence THEN RETURN j.network_failures;END IF;
 INSERT INTO ai_review_v4._ctx VALUES(pg_backend_pid(),txid_current());UPDATE ai_review_v4.jobs SET network_failures=network_failures+1,last_failure_fence=network_failure_v4.fence WHERE id=wanted RETURNING * INTO j;DELETE FROM ai_review_v4._ctx WHERE pid=pg_backend_pid();RETURN j.network_failures;
END $$;
CREATE FUNCTION ai_review_v4.defer_v4(wanted uuid,owner uuid,token uuid,fence bigint,code text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,ai_review_v4,pg_temp AS $$ BEGIN
 PERFORM ai_review_v4._assert();PERFORM ai_review_v4._lease(wanted,owner,token,fence);IF code IS NULL OR code NOT IN('TENANT_NOT_ADMITTED','CONFIGURATION_CHANGED','NETWORK_RETRY','RESULT_UNCONFIRMED','WORKER_INTERRUPTED') THEN RAISE EXCEPTION 'AI_REVIEW_INPUT';END IF;
 INSERT INTO ai_review_v4._ctx VALUES(pg_backend_pid(),txid_current());UPDATE ai_review_v4.jobs SET status='RETRY',owner=NULL,token=NULL,lease_until=NULL,available_at=clock_timestamp()+interval '3 seconds',error_code=code WHERE id=wanted;DELETE FROM ai_review_v4._ctx WHERE pid=pg_backend_pid();
END $$;
CREATE FUNCTION ai_review_v4.result_v4(wanted uuid,owner uuid,token uuid,fence bigint,sealed jsonb,digest text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,ai_review_v4,pg_temp AS $$ BEGIN
 PERFORM ai_review_v4._assert();PERFORM ai_review_v4._lease(wanted,owner,token,fence);IF sealed IS NULL OR jsonb_typeof(sealed)<>'object' OR octet_length(sealed::text)>100000 OR digest IS NULL OR digest!~'^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'AI_REVIEW_INPUT';END IF;
 INSERT INTO ai_review_v4._ctx VALUES(pg_backend_pid(),txid_current());UPDATE ai_review_v4.jobs SET status='RESULT_READY',outcome_sealed=sealed,outcome_digest=digest,completed_at=clock_timestamp(),owner=NULL,token=NULL,lease_until=NULL,error_code=NULL WHERE id=wanted;DELETE FROM ai_review_v4._ctx WHERE pid=pg_backend_pid();
END $$;
REVOKE ALL ON SCHEMA ai_review_v4 FROM PUBLIC;REVOKE ALL ON ALL TABLES IN SCHEMA ai_review_v4 FROM PUBLIC,__APP__;REVOKE ALL ON ALL SEQUENCES IN SCHEMA ai_review_v4 FROM PUBLIC,__APP__;REVOKE ALL ON ALL FUNCTIONS IN SCHEMA ai_review_v4 FROM PUBLIC,__APP__;
GRANT USAGE ON SCHEMA ai_review_v4 TO __APP__;
GRANT EXECUTE ON FUNCTION ai_review_v4.verify_v4(),ai_review_v4.enqueue_v4(jsonb,text,jsonb),ai_review_v4.read_v4(uuid),ai_review_v4.claim_v4(uuid,uuid),ai_review_v4.renew_v4(uuid,uuid,uuid,bigint),ai_review_v4.dispatch_v4(uuid,uuid,uuid,bigint),ai_review_v4.defer_v4(uuid,uuid,uuid,bigint,text),ai_review_v4.network_failure_v4(uuid,uuid,uuid,bigint),ai_review_v4.result_v4(uuid,uuid,uuid,bigint,jsonb,text) TO __APP__;
RESET ROLE;
CREATE FUNCTION ai_review_v4._ddl_start() RETURNS event_trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,ai_review_v4,pg_temp AS $$ BEGIN PERFORM pg_advisory_xact_lock(1229213011,1);PERFORM pg_advisory_xact_lock(1229213011,2);PERFORM pg_advisory_xact_lock(1229213011,4);END $$;
CREATE FUNCTION ai_review_v4._ddl_end() RETURNS event_trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,ai_review_v4,pg_temp AS $$ BEGIN IF EXISTS(SELECT 1 FROM pg_event_trigger_ddl_commands() WHERE schema_name='ai_review_v4') THEN PERFORM nextval('ai_review_v4._ddl_epoch');END IF;END $$;
CREATE FUNCTION ai_review_v4._sql_drop() RETURNS event_trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,ai_review_v4,pg_temp AS $$ BEGIN IF EXISTS(SELECT 1 FROM pg_event_trigger_dropped_objects() WHERE schema_name='ai_review_v4') THEN PERFORM nextval('ai_review_v4._ddl_epoch');END IF;END $$;
REVOKE ALL ON FUNCTION ai_review_v4._ddl_start(),ai_review_v4._ddl_end(),ai_review_v4._sql_drop() FROM PUBLIC;
CREATE EVENT TRIGGER ai_review_ddl_start_v4 ON ddl_command_start EXECUTE FUNCTION ai_review_v4._ddl_start();CREATE EVENT TRIGGER ai_review_ddl_end_v4 ON ddl_command_end EXECUTE FUNCTION ai_review_v4._ddl_end();CREATE EVENT TRIGGER ai_review_sql_drop_v4 ON sql_drop EXECUTE FUNCTION ai_review_v4._sql_drop();
ALTER EVENT TRIGGER ai_review_ddl_start_v4 ENABLE ALWAYS;ALTER EVENT TRIGGER ai_review_ddl_end_v4 ENABLE ALWAYS;ALTER EVENT TRIGGER ai_review_sql_drop_v4 ENABLE ALWAYS;

